on conflict (id) do update set level = excluded.level, category_id = excluded.category_id, sort = excluded.sort,
  title = excluded.title, title_ru = excluded.title_ru, summary = excluded.summary, content = excluded.content,
  line_count = excluded.line_count, vocab_count = excluded.vocab_count;

on conflict (id) do update set ru = excluded.ru, stressed = excluded.stressed, en = excluded.en, pos = excluded.pos,
  note = excluded.note, tags = excluded.tags, level = excluded.level, lesson_id = excluded.lesson_id;

on conflict (id) do update set level = excluded.level, title = excluded.title, summary = excluded.summary, pass_pct = excluded.pass_pct, sort = excluded.sort;

on conflict (id) do update set test_id = excluded.test_id, sort = excluded.sort, level = excluded.level, kind = excluded.kind,
  prompt = excluded.prompt, ru = excluded.ru, options = excluded.options, answer = excluded.answer;

on conflict (id) do update set level = excluded.level, category_id = excluded.category_id, sort = excluded.sort, title = excluded.title,
  title_ru = excluded.title_ru, description = excluded.description, tutor_role = excluded.tutor_role, script = excluded.script;

on conflict (id) do update set level = excluded.level, sort = excluded.sort, title = excluded.title, summary = excluded.summary,
  focus = excluded.focus, items = excluded.items, pass_count = excluded.pass_count;
